recipes.code:
{
  "inputs": [
    {
      "id": "dse-api-key",
      "type": "promptString",
      "description": "Dead Simple Email API key (starts with dse_). Get one instantly with no signup form: POST https://api.deadsimple.email/v1/auth/agent-signup",
      "password": true
    }
  ],
  "servers": {
    "dead-simple-email": {
      "type": "stdio",
      "command": "python3",
      "args": [
        "-m",
        "deadsimple-email"
      ],
      "env": {
        "DSE_API_KEY": "${input:dse-api-key}"
      }
    }
  }
}
